questionvariables.text:
/* Shared Question Bank Place Value, Rounding and Standard Form PVRS-05
Diagnostic task: contrast decimal-place rounding with significant-figure rounding.
Reference-only interaction sources: NUMBAS-21514 NUMBAS-169559 NUMBAS-21530
This question is independently authored. No source wording or mathematical content is copied. */
/* Use a number between 10 and 99 with three decimal digits.
We deliberately choose: 2 decimal places 3 significant figures
For numbers in this range, these require different rounding places: 2 d.p. -> hundredths 3 s.f. -> tenths */
dp_count: 2;
sf_count: 3;
/* Generate digits.
The hundredths digit is at least 5 so 3 significant figures requires rounding the tenths digit upward.
The thousandths digit is at least 5 so 2 decimal places requires rounding the hundredths digit upward.
This ensures both operations are active and the two answers are distinct. */
tens_digit: rand_with_prohib(1,8,[]);
ones_digit: rand_with_prohib(0,9,[]);
tenths_digit: rand_with_prohib(0,8,[]);
hundredths_digit: rand_with_prohib(5,8,[]);
thousandths_digit: rand_with_prohib(5,9,[]);
number: tens_digit*10 + ones_digit + tenths_digit/10 + hundredths_digit/100 + thousandths_digit/1000;
/* 2 decimal places: round to nearest hundredth. */
answer_dp: floor( number*100 + 1/2 )/100;
/* 3 significant figures for a number between 10 and 99: round to nearest tenth. */
answer_sf: floor( number*10 + 1/2 )/10;
/* Diagnostic misconception: learner treats the instructions as equivalent and swaps the two procedures. */
wrong_dp_as_sf: answer_sf;
wrong_sf_as_dp: answer_dp;
/* Display decimals while preserving exact rational arithmetic internally. */
number_display: float(number);
answer_dp_display: float(answer_dp);
answer_sf_display: float(answer_sf);
